-- Edition documents are shared product facts only. Personal records/recommendation prose never enter this table.
create table public.product_catalog (
 id text primary key check(id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(id)<=160),
 family_id text not null check(family_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(family_id)<=160),
 category public.drink_category not null check(category in ('whisky','wine','beer','traditional')),
 normalized_name text not null check(length(normalized_name) between 1 and 300),
 document jsonb not null,
 status text not null default 'candidate' check(status in ('candidate','verified','held')),
 verified_at timestamptz,
 revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 check(jsonb_typeof(document)='object' and octet_length(document::text)<=65536),
 check(document ?& array['id','familyId','name','category','edition','aliases','baseAliases','features','source','description']),
 check(document->>'id'=id and document->>'familyId'=family_id and document->>'category'=category::text),
 check(jsonb_typeof(document->'name')='string' and length(document->>'name') between 1 and 300),
 check(jsonb_typeof(document->'edition')='string' and length(document->>'edition') between 1 and 300),
 check(jsonb_typeof(document->'aliases')='array' and jsonb_typeof(document->'baseAliases')='array' and jsonb_typeof(document->'features')='array'),
 check(jsonb_typeof(document->'source')='object' and document->'source' ?& array['url','kind','title','checkedAt']),
 check((document->'source'->>'url') ~ '^https://[^/@[:space:]]+\.[^/@[:space:]]+(/|$)' and length(document->'source'->>'url')<=2048),
 check(document->'source'->>'kind' in ('producer','expert-tasting')),
 check(status<>'verified' or (verified_at is not null and jsonb_array_length(document->'features')>0))
);
create index product_catalog_verified_category on public.product_catalog(category,id) where status='verified';
create index product_catalog_family on public.product_catalog(family_id);
create index product_catalog_lookup on public.product_catalog(normalized_name);
alter table public.product_catalog enable row level security;
create policy product_catalog_read on public.product_catalog for select to authenticated
 using(status='verified' and private.active_user());
revoke all on public.product_catalog from public,anon,authenticated;
grant select on public.product_catalog to authenticated;
grant all on public.product_catalog to service_role;
